import React from 'react';
import Link from 'next/link';
import { AlertTriangle, ChevronRight } from 'lucide-react';
import type { MonitoredSiteWithLatestCheck } from '@pingwatch/shared';

interface IncidentBannerProps {
  downSites: MonitoredSiteWithLatestCheck[];
}

export function IncidentBanner({ downSites }: IncidentBannerProps) {
  if (!downSites || downSites.length === 0) return null;

  return (
    <div className="mb-6 p-4 rounded-lg bg-[#FF4D4F]/10 border border-[#FF4D4F]/40 flex flex-col md:flex-row md:items-center justify-between gap-4 animate-in fade-in duration-300">
      <div className="flex items-start md:items-center gap-3">
        <div className="p-2 rounded bg-[#FF4D4F]/20 text-[#FF4D4F] flex-shrink-0">
          <AlertTriangle className="h-5 w-5" />
        </div>
        <div>
          <h3 className="text-sm font-semibold text-[#FF4D4F] flex items-center gap-2">
            <span>Downtime Incident Detected</span>
            <span className="text-xs px-2 py-0.5 rounded-full bg-[#FF4D4F]/20 font-mono">
              {downSites.length} {downSites.length === 1 ? 'service down' : 'services down'}
            </span>
          </h3>
          <p className="text-xs text-[#E6EDF3] mt-0.5">
            {downSites.map((s) => s.name).join(', ')} failed health checks. Notifications dispatched to active alert channels.
          </p>
        </div>
      </div>

      <div className="flex items-center gap-2 self-end md:self-center">
        {downSites.length === 1 ? (
          <Link
            href={`/dashboard/sites/${downSites[0].id}`}
            className="inline-flex items-center gap-1 text-xs font-medium text-white hover:text-[#00FF87] transition-colors"
          >
            Investigate Incident <ChevronRight className="h-3.5 w-3.5" />
          </Link>
        ) : (
          <span className="text-xs font-mono text-[#8B949E]">Check cards below</span>
        )}
      </div>
    </div>
  );
}
